static const char* b2s(bool b) { return b ? "True" : "False"; }

template <typename T>
class MiniSharedPtr {
    struct ControlBlock {
        std::atomic<long> shared;
        std::atomic<long> weak;
        explicit ControlBlock(long s) : shared(s), weak(1) {}
    };
    T* ptr_ = nullptr;
    ControlBlock* cb_ = nullptr;

    void release_shared() {
        if (!cb_) return;
        if (--cb_->shared == 0) {
            delete ptr_;
            ptr_ = nullptr;
            if (--cb_->weak == 0) delete cb_;
        }
        cb_ = nullptr;
    }
public:
    MiniSharedPtr() = default;
    explicit MiniSharedPtr(T* p) : ptr_(p), cb_(p ? new ControlBlock(1) : nullptr) {}
    MiniSharedPtr(const MiniSharedPtr& o) : ptr_(o.ptr_), cb_(o.cb_) { if (cb_) ++cb_->shared; }
    MiniSharedPtr(MiniSharedPtr&& o) noexcept : ptr_(o.ptr_), cb_(o.cb_) { o.ptr_ = nullptr; o.cb_ = nullptr; }
    MiniSharedPtr& operator=(const MiniSharedPtr& o) {
        if (this == &o) return *this;
        MiniSharedPtr tmp(o);
        swap(tmp);
        return *this;
    }
    MiniSharedPtr& operator=(MiniSharedPtr&& o) noexcept {
        if (this != &o) { swap(o); o.release_shared(); }
        return *this;
    }
    ~MiniSharedPtr() { release_shared(); }
    void swap(MiniSharedPtr& o) noexcept { std::swap(ptr_, o.ptr_); std::swap(cb_, o.cb_); }

    long use_count() const { return cb_ ? cb_->shared.load() : 0; }
    T& operator*() const { return *ptr_; }
    T* get() const { return ptr_; }
};

int main() {
    MiniSharedPtr<int> a(new int(42));
    std::cout << "after ctor use_count=" << a.use_count() << "\n";

    {
        MiniSharedPtr<int> b = a;              // 拷贝 +1
        std::cout << "after copy use_count=" << a.use_count() << "\n";

        MiniSharedPtr<int> c;
        c = b;                                 // 拷贝赋值 +1
        std::cout << "after assign use_count=" << a.use_count() << "\n";
        std::cout << "value via c=" << *c << "\n";
    }

    std::cout << "after scope use_count=" << a.use_count() << "\n";

    MiniSharedPtr<int> d = std::move(a);       // 移动不改变计数
    std::cout << "after move use_count=" << d.use_count() << "\n";
    std::cout << "moved-from holds nothing: " << b2s(a.get() == nullptr) << "\n";
}
